def crear_vestido_en_tienda(apps, schema_editor):
    """Crea 'Vestido en tienda' con su ruta T (sin compra de materiales)."""
    TipoVestido = apps.get_model("core", "TipoVestido")
    RutaProduccion = apps.get_model("core", "RutaProduccion")
    Operacion = apps.get_model("core", "Operacion")
    PlantillaOperacion = apps.get_model("core", "PlantillaOperacion")

    # Si aún no se cargó el catálogo, cargar_catalogo_inicial() lo crea luego.
    if not Operacion.objects.exists():
        return

    vestido, _ = TipoVestido.objects.get_or_create(
        nombre="Vestido en tienda",
        defaults={"descripcion": "Vestido de stock de la tienda que solo pasa por modificaciones (sin compra de materiales)."},
    )
    ruta, _ = RutaProduccion.objects.get_or_create(
        tipo_vestido=vestido, taller="T",
        defaults={"descripcion": "Modificación de vestido en stock"},
    )
    for orden, (nombre, horas) in enumerate(TIEMPOS, start=1):
        operacion = Operacion.objects.filter(nombre__iexact=nombre).first()
        if operacion is None:
            continue
        PlantillaOperacion.objects.get_or_create(
            ruta=ruta, operacion=operacion,
            defaults={
                "orden": orden,
                "horas_estimadas": Decimal(str(horas)),
                "tipo_tiempo": "TRABAJO",
                "obligatoria": nombre != "bordado",
                "activa": True,
            },
        )


